<?php
use RcnSistemas\Services\Licenses\LicenseCatalog;
use RcnSistemas\Services\Licenses\QuotationCatalog;

$escape = static fn (mixed $value): string => htmlspecialchars((string) ($value ?? ''), ENT_QUOTES, 'UTF-8');
$query = static fn (int $targetPage): string => http_build_query(['search' => $filter->search, 'status' => $filter->status, 'month' => $filter->month ?? '', 'year' => $filter->year ?? '', 'per_page' => $perPage, 'page' => $targetPage]);
$returnTo = '/admin/licencias?' . $query($page);
$url = static fn (int $targetPage): string => $baseUrl . '/admin/licencias?' . $query($targetPage);
?>
<section class="section">
    <header class="admin-header"><div><h1>Licencias</h1><p>Consulta las licencias de tus clientes y sus vencimientos. Para registrar una, entra a la ficha del cliente.</p></div><div class="ticket-header-actions"><a href="<?php echo $baseUrl; ?>/admin/clientes" class="btn">Ir a clientes</a></div></header>
    <?php require __DIR__ . '/_notice.php'; ?>
    <div class="card panel-card"><form method="get" class="admin-form"><div class="admin-form__row">
        <div class="admin-form__group"><label class="admin-form__label" for="search">Buscar licencia</label><input id="search" name="search" class="admin-form__input" value="<?php echo $escape($filter->search); ?>" placeholder="Cliente, razón social, RFC, sistema, alias o número de serie"></div>
        <div class="admin-form__group"><label class="admin-form__label" for="status">Estado</label><select id="status" name="status" class="admin-form__input"><?php foreach (LicenseCatalog::listFilters() as $value => $label): ?><option value="<?php echo $escape($value); ?>" <?php echo $filter->status === $value ? 'selected' : ''; ?>><?php echo $escape($label); ?></option><?php endforeach; ?></select></div>
    </div><div class="admin-form__row admin-form__row--triple">
        <div class="admin-form__group"><label class="admin-form__label" for="month">Mes de vencimiento</label><select id="month" name="month" class="admin-form__input"><option value="">Todos</option><?php foreach (LicenseCatalog::months() as $number => $label): ?><option value="<?php echo $number; ?>" <?php echo $filter->month === $number ? 'selected' : ''; ?>><?php echo $escape($label); ?></option><?php endforeach; ?></select></div>
        <div class="admin-form__group"><label class="admin-form__label" for="year">Año de vencimiento</label><select id="year" name="year" class="admin-form__input"><option value="">Todos</option><?php foreach ($years as $yearOption): ?><option value="<?php echo (int) $yearOption; ?>" <?php echo $filter->year === $yearOption ? 'selected' : ''; ?>><?php echo (int) $yearOption; ?></option><?php endforeach; ?></select></div>
        <div class="admin-form__group"><label class="admin-form__label" for="per_page">Mostrar</label><select id="per_page" name="per_page" class="admin-form__input"><?php foreach ([10, 25, 50] as $size): ?><option value="<?php echo $size; ?>" <?php echo $perPage === $size ? 'selected' : ''; ?>><?php echo $size; ?></option><?php endforeach; ?></select></div>
    </div><div class="admin-form__buttons"><a href="<?php echo $baseUrl; ?>/admin/licencias" class="btn btn--secondary">Limpiar</a><button type="submit" class="btn">Filtrar</button></div></form></div>
    <div class="ticket-toolbar"><div class="ticket-results-summary"><strong><?php echo (int) $total; ?></strong> licencia<?php echo $total === 1 ? '' : 's'; ?> encontrada<?php echo $total === 1 ? '' : 's'; ?><span class="ticket-results-summary__page">Página <?php echo (int) $page; ?> de <?php echo (int) $totalPages; ?></span></div></div>
    <?php if ($totalPages > 1): ?><nav class="pagination" aria-label="Paginación de licencias"><?php if ($page > 1): ?><a href="<?php echo $escape($url($page - 1)); ?>" class="pagination__link">Anterior</a><?php endif; ?><?php for ($pageNumber = 1; $pageNumber <= $totalPages; $pageNumber++): ?><a href="<?php echo $escape($url($pageNumber)); ?>" class="pagination__link <?php echo $pageNumber === $page ? 'pagination__link--active' : ''; ?>"><?php echo $pageNumber; ?></a><?php endfor; ?><?php if ($page < $totalPages): ?><a href="<?php echo $escape($url($page + 1)); ?>" class="pagination__link">Siguiente</a><?php endif; ?></nav><?php endif; ?>
    <div class="table-wrapper"><table class="table table--tickets"><thead><tr><th>Cliente</th><th>Sistema</th><th>Tipo</th><th>Usuarios</th><th>Serie</th><th>Vence</th><th>Estado</th><th>Última cotización</th><th>Acciones</th></tr></thead><tbody>
        <?php if (!$licenses): ?><tr><td colspan="9">No se encontraron licencias.</td></tr><?php else: ?><?php foreach ($licenses as $item): ?>
            <?php $itemStatus = LicenseCatalog::status($item['license_type'], $item['expires_at'], $today); ?>
            <tr><td data-label="Cliente"><a class="ticket-primary-link" href="<?php echo $baseUrl; ?>/admin/clientes/<?php echo (int) $item['customer_id']; ?>"><?php echo $escape($item['customer_name']); ?></a><?php if (!empty($item['business_name'])): ?><br><span class="ticket-muted"><?php echo $escape($item['business_name']); ?></span><?php endif; ?></td><td data-label="Sistema"><?php if (!empty($item['alias'])): ?><strong><?php echo $escape($item['alias']); ?></strong><br><span class="ticket-muted"><?php echo $escape($item['product_name']); ?></span><?php else: ?><?php echo $escape($item['product_name']); ?><?php endif; ?></td><td data-label="Tipo"><?php echo $escape(LicenseCatalog::typeLabel($item['license_type'])); ?> · <?php echo $escape(LicenseCatalog::rfcScopeLabel($item['rfc_scope'])); ?></td><td data-label="Usuarios"><?php echo (int) $item['users_count']; ?></td><td data-label="Serie"><?php echo $escape($item['serial_number'] ?: 'Sin registrar'); ?></td><td data-label="Vence"><?php echo $item['expires_at'] ? $escape(date('d/m/Y', strtotime($item['expires_at']))) : 'No aplica'; ?></td><td data-label="Estado"><span class="ticket-status ticket-status--<?php echo $escape(str_replace('_', '-', $itemStatus)); ?>"><span class="ticket-status__dot"></span><?php echo $escape(LicenseCatalog::statusLabel($itemStatus)); ?></span></td><td data-label="Última cotización"><?php if (!empty($item['last_quotation_folio'])): ?><?php echo $escape($item['last_quotation_folio']); ?><br><span class="ticket-status ticket-status--<?php echo $escape($item['last_quotation_status']); ?>"><span class="ticket-status__dot"></span><?php echo $escape(QuotationCatalog::statusLabel($item['last_quotation_status'])); ?></span><?php else: ?><span class="ticket-muted">Sin cotización</span><?php endif; ?></td><td data-label="Acciones"><a class="table__action" href="<?php echo $baseUrl; ?>/admin/licencias/<?php echo (int) $item['id']; ?>/editar">Editar</a> <?php $renewId = (int) $item['id']; $renewType = $item['license_type']; $renewExpiresAt = $item['expires_at']; $renewReturnTo = $returnTo; require __DIR__ . '/_renew_button.php'; ?></td></tr>
        <?php endforeach; ?><?php endif; ?>
    </tbody></table></div>
</section>
